import type {
  ReferenceSelection,
  ReferenceSource,
  ReferenceVersion,
} from "./types";

/** WHO Child Growth Standards, 2006 (0–60 months). */
export const WHO_2006_VERSION: ReferenceVersion = "WHO-2006";

/** Indian Academy of Pediatrics revised growth charts, 2015 (5–18 years). */
export const IAP_2015_VERSION: ReferenceVersion = "IAP-2015";

export const WHO_AGE_MAX_MONTHS = 60;
export const IAP_AGE_MIN_MONTHS = 60;
export const IAP_AGE_MAX_MONTHS = 216; // 18 years

/**
 * Auto-select growth reference by age.
 *
 * - age < 60 months → WHO / WHO-2006
 * - age ≥ 60 months → IAP / IAP-2015
 *
 * CDC charts are never used in this application.
 */
export function selectReference(
  ageMonths: number,
  forceSource?: ReferenceSource
): ReferenceSelection {
  if (!Number.isFinite(ageMonths) || ageMonths < 0) {
    return {
      source: "WHO",
      version: WHO_2006_VERSION,
      reason: "Invalid/negative age — defaulting to WHO-2006.",
    };
  }

  if (forceSource === "WHO") {
    return {
      source: "WHO",
      version: WHO_2006_VERSION,
      reason: "Forced WHO (WHO Child Growth Standards 2006).",
    };
  }

  if (forceSource === "IAP") {
    return {
      source: "IAP",
      version: IAP_2015_VERSION,
      reason: "Forced IAP (IAP Growth Charts 2015).",
    };
  }

  if (ageMonths < WHO_AGE_MAX_MONTHS) {
    return {
      source: "WHO",
      version: WHO_2006_VERSION,
      reason: `Age ${ageMonths.toFixed(1)} mo < 60 — WHO Child Growth Standards 2006.`,
    };
  }

  return {
    source: "IAP",
    version: IAP_2015_VERSION,
    reason: `Age ${ageMonths.toFixed(1)} mo ≥ 60 — IAP Growth Charts 2015.`,
  };
}

/** True when WHO WEIGHT_FOR_HEIGHT is applicable (typically <60 months). */
export function supportsWeightForHeight(
  source: ReferenceSource,
  ageMonths: number
): boolean {
  return source === "WHO" && ageMonths < WHO_AGE_MAX_MONTHS;
}

/** Head circumference WHO standards are typically published to 36 months. */
export function supportsHeadCircumference(
  source: ReferenceSource,
  ageMonths: number
): boolean {
  if (source === "WHO") return ageMonths <= 36;
  return false;
}

export function describeReferenceVersions(): {
  who: string;
  iap: string;
  cdc: string;
} {
  return {
    who: "WHO-2006 — WHO Child Growth Standards (0–60 months)",
    iap: "IAP-2015 — Indian Academy of Pediatrics revised charts (5–18 years)",
    cdc: "CDC — not used by this application",
  };
}

import type { LmsParams, LmsPoint } from "./types";

const L_NEAR_ZERO = 1e-7;
export const Z_CLAMP = 3;

/**
 * Official LMS (Box-Cox) Z-score.
 * If L ≈ 0:  ln(x/M) / S
 * Else:      (((x/M)^L) - 1) / (L * S)
 */
export function zScore(x: number, L: number, M: number, S: number): number {
  if (!(x > 0) || !(M > 0) || !(S > 0) || !Number.isFinite(L)) {
    return Number.NaN;
  }

  if (Math.abs(L) < L_NEAR_ZERO) {
    return Math.log(x / M) / S;
  }

  return (Math.pow(x / M, L) - 1) / (L * S);
}

export function zScoreFromParams(x: number, params: LmsParams): number {
  return zScore(x, params.L, params.M, params.S);
}

/** Clamp Z to ±3 for classification display; raw Z is kept separately by callers. */
export function clampZ(z: number, limit: number = Z_CLAMP): number {
  if (!Number.isFinite(z)) return z;
  return Math.max(-limit, Math.min(limit, z));
}

/** Standard normal PDF φ(z). */
export function normalPdf(z: number): number {
  return Math.exp(-0.5 * z * z) / Math.sqrt(2 * Math.PI);
}

/**
 * Abramowitz & Stegun 26.2.17 approximation of the standard normal CDF Φ(z).
 * Absolute error typically < 7.5e-8.
 */
export function normalCdf(z: number): number {
  if (!Number.isFinite(z)) return Number.NaN;
  if (z > 8) return 1;
  if (z < -8) return 0;

  const sign = z < 0 ? -1 : 1;
  const absZ = Math.abs(z);
  const t = 1 / (1 + 0.2316419 * absZ);
  const d = 0.3989423 * Math.exp((-absZ * absZ) / 2);
  const p =
    d *
    t *
    (0.3193815 +
      t * (-0.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274))));

  const cdf = sign === 1 ? 1 - p : p;
  return Math.min(1, Math.max(0, cdf));
}

/** Percentile (0–100) from Z via normal CDF. */
export function percentileFromZ(z: number): number {
  if (!Number.isFinite(z)) return Number.NaN;
  return normalCdf(z) * 100;
}

/**
 * Inverse LMS: measurement for a given Z.
 * x = M * (1 + L*S*Z)^(1/L)   when L ≠ 0
 * x = M * exp(S*Z)             when L ≈ 0
 */
export function valueFromZ(z: number, L: number, M: number, S: number): number {
  if (!Number.isFinite(z) || !(M > 0) || !(S > 0) || !Number.isFinite(L)) {
    return Number.NaN;
  }

  if (Math.abs(L) < L_NEAR_ZERO) {
    return M * Math.exp(S * z);
  }

  const inner = 1 + L * S * z;
  if (inner <= 0) {
    // Outside the support of the Box-Cox transform
    return Number.NaN;
  }
  return M * Math.pow(inner, 1 / L);
}

export function valueFromZParams(z: number, params: LmsParams): number {
  return valueFromZ(z, params.L, params.M, params.S);
}

/**
 * Approximate inverse normal CDF (Acklam / Beasley-Springer style rational approx).
 * Sufficient for chart percentile → Z conversion.
 */
export function zFromPercentile(percentile: number): number {
  if (!Number.isFinite(percentile)) return Number.NaN;
  const p = percentile / 100;
  if (p <= 0) return -Infinity;
  if (p >= 1) return Infinity;
  if (p === 0.5) return 0;

  // Coefficients for Acklam's approximation
  const a = [
    -3.969683028665376e1, 2.209460984245205e2, -2.759285104469687e2,
    1.383577459334652e2, -3.066479806614716e1, 2.506628277459239,
  ];
  const b = [
    -5.447609879822406e1, 1.615858368580409e2, -1.556989798598866e2,
    6.680131188771972e1, -1.328068155288572e1,
  ];
  const c = [
    -7.784894002430293e-3, -3.223964580411365e-1, -2.400758277161838,
    -2.549732539343734, 4.374664141464968, 2.938163982698783,
  ];
  const d = [
    7.784695709041462e-3, 3.224671290700398e-1, 2.445134137142996,
    3.754408661907416,
  ];

  const plow = 0.02425;
  const phigh = 1 - plow;
  let q: number;

  if (p < plow) {
    q = Math.sqrt(-2 * Math.log(p));
    return (
      (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
      ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
    );
  }

  if (p > phigh) {
    q = Math.sqrt(-2 * Math.log(1 - p));
    return -(
      (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
      ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
    );
  }

  q = p - 0.5;
  const r = q * q;
  return (
    ((((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q) /
    (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1)
  );
}

/** Measurement corresponding to a percentile under LMS. */
export function valueFromPercentile(
  percentile: number,
  L: number,
  M: number,
  S: number
): number {
  return valueFromZ(zFromPercentile(percentile), L, M, S);
}

export function valueFromPercentileParams(
  percentile: number,
  params: LmsParams
): number {
  return valueFromPercentile(percentile, params.L, params.M, params.S);
}

function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

/**
 * Linearly interpolate LMS between two adjacent reference points by xValue
 * (age months or height cm). Points must be sorted ascending by xValue.
 */
export function interpolateLms(
  points: readonly LmsPoint[],
  xValue: number
): LmsParams | null {
  if (!points.length || !Number.isFinite(xValue)) return null;

  if (points.length === 1) {
    const p = points[0]!;
    return { L: p.L, M: p.M, S: p.S };
  }

  // Exact hit
  for (const p of points) {
    if (Math.abs(p.xValue - xValue) < 1e-9) {
      return { L: p.L, M: p.M, S: p.S };
    }
  }

  // Below / above range → clamp to nearest endpoint (WHO practice for edge ages)
  if (xValue <= points[0]!.xValue) {
    const p = points[0]!;
    return { L: p.L, M: p.M, S: p.S };
  }
  const last = points[points.length - 1]!;
  if (xValue >= last.xValue) {
    return { L: last.L, M: last.M, S: last.S };
  }

  // Binary search for bracket
  let lo = 0;
  let hi = points.length - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (points[mid]!.xValue <= xValue) lo = mid;
    else hi = mid;
  }

  const a = points[lo]!;
  const b = points[hi]!;
  const span = b.xValue - a.xValue;
  const t = span === 0 ? 0 : (xValue - a.xValue) / span;

  return {
    L: lerp(a.L, b.L, t),
    M: lerp(a.M, b.M, t),
    S: lerp(a.S, b.S, t),
  };
}

/** Convenience: Z + percentile + clamp metadata for a measurement. */
export function computeZScoreResult(
  x: number,
  params: LmsParams
): { z: number; zClamped: number; percentile: number; isExtreme: boolean } {
  const z = zScoreFromParams(x, params);
  const zClamped = clampZ(z);
  return {
    z,
    zClamped,
    percentile: percentileFromZ(z),
    isExtreme: Number.isFinite(z) && Math.abs(z) > Z_CLAMP,
  };
}

/** Standard chart percentile set derived from LMS. */
export function derivedPercentiles(params: LmsParams): {
  p3: number;
  p15: number;
  p50: number;
  p85: number;
  p97: number;
} {
  return {
    p3: valueFromPercentileParams(3, params),
    p15: valueFromPercentileParams(15, params),
    p50: valueFromPercentileParams(50, params),
    p85: valueFromPercentileParams(85, params),
    p97: valueFromPercentileParams(97, params),
  };
}

import {
  computeZScoreResult,
  interpolateLms,
} from "./lms";
import { interpretGrowth } from "./interpretation";
import {
  selectReference,
  supportsHeadCircumference,
  supportsWeightForHeight,
} from "./reference-selector";
import type {
  AssessGrowthInput,
  GrowthAssessment,
  GrowthIndicator,
  GrowthVelocity,
  LmsPoint,
  PreviousVisitSnapshot,
  ReferenceDataProvider,
  Sex,
  ZScoreResult,
} from "./types";

/** BMI = weight(kg) / (height(m))^2 */
export function computeBmi(weightKg: number, heightCm: number): number {
  if (!(weightKg > 0) || !(heightCm > 0)) return Number.NaN;
  const m = heightCm / 100;
  return weightKg / (m * m);
}

function buildZResult(
  indicator: GrowthIndicator,
  value: number,
  points: LmsPoint[],
  xValue: number
): ZScoreResult | null {
  const params = interpolateLms(points, xValue);
  if (!params) return null;
  const scored = computeZScoreResult(value, params);
  if (!Number.isFinite(scored.z)) return null;
  return {
    ...scored,
    indicator,
    value,
    expected: params.M,
    L: params.L,
    M: params.M,
    S: params.S,
  };
}

function monthsBetween(
  previous: PreviousVisitSnapshot,
  currentAgeMonths: number
): number {
  if (
    Number.isFinite(previous.ageMonths) &&
    Number.isFinite(currentAgeMonths)
  ) {
    const d = currentAgeMonths - previous.ageMonths;
    if (d > 0) return d;
  }
  return Number.NaN;
}

export function computeGrowthVelocity(
  previous: PreviousVisitSnapshot,
  current: { ageMonths: number; weightKg: number; heightCm: number }
): GrowthVelocity {
  const intervalMonths = monthsBetween(previous, current.ageMonths);
  const notes: string[] = [];

  if (!Number.isFinite(intervalMonths) || intervalMonths <= 0) {
    return {
      weightKgPerMonth: null,
      heightCmPerMonth: null,
      intervalMonths: 0,
      notes: ["Previous visit age must be earlier than current visit."],
    };
  }

  const weightKgPerMonth =
    (current.weightKg - previous.weightKg) / intervalMonths;
  const heightCmPerMonth =
    (current.heightCm - previous.heightCm) / intervalMonths;

  // Rough clinical heuristics (not WHO formal velocity standards)
  if (weightKgPerMonth < 0) {
    notes.push("Weight loss since previous visit.");
  } else if (weightKgPerMonth < 0.05 && current.ageMonths < 24) {
    notes.push("Low weight velocity for infancy/toddler age.");
  }

  if (heightCmPerMonth < 0) {
    notes.push("Apparent height decrease — verify measurement technique.");
  } else if (heightCmPerMonth < 0.3 && current.ageMonths < 24) {
    notes.push("Low linear growth velocity.");
  }

  if (
    previous.weightForAgeZ != null &&
    Number.isFinite(previous.weightForAgeZ) &&
    weightKgPerMonth < 0
  ) {
    notes.push("Possible growth faltering (weight).");
  }

  return {
    weightKgPerMonth,
    heightCmPerMonth,
    intervalMonths,
    notes,
  };
}

export class GrowthCalculator {
  constructor(private readonly provider: ReferenceDataProvider) {}

  async assessGrowth(input: AssessGrowthInput): Promise<GrowthAssessment> {
    const { sex, ageMonths, weightKg, heightCm } = input;
    const headCm = input.headCm ?? null;

    if (!(ageMonths >= 0) || !Number.isFinite(ageMonths)) {
      throw new Error("ageMonths must be a non-negative finite number");
    }
    if (!(weightKg > 0) || !(heightCm > 0)) {
      throw new Error("weightKg and heightCm must be positive");
    }

    const reference = selectReference(ageMonths, input.forceSource);
    const bmi = computeBmi(weightKg, heightCm);

    const load = (indicator: GrowthIndicator) =>
      Promise.resolve(
        this.provider.getLmsPoints(
          reference.source,
          reference.version,
          indicator,
          sex
        )
      );

    const [wfaPts, hfaPts, bmiPts] = await Promise.all([
      load("WEIGHT_FOR_AGE"),
      load("HEIGHT_FOR_AGE"),
      load("BMI_FOR_AGE"),
    ]);

    const weightForAge = buildZResult(
      "WEIGHT_FOR_AGE",
      weightKg,
      wfaPts,
      ageMonths
    );
    const heightForAge = buildZResult(
      "HEIGHT_FOR_AGE",
      heightCm,
      hfaPts,
      ageMonths
    );
    const bmiForAge = Number.isFinite(bmi)
      ? buildZResult("BMI_FOR_AGE", bmi, bmiPts, ageMonths)
      : null;

    let weightForHeight: ZScoreResult | null = null;
    if (supportsWeightForHeight(reference.source, ageMonths)) {
      const wfhPts = await load("WEIGHT_FOR_HEIGHT");
      weightForHeight = buildZResult(
        "WEIGHT_FOR_HEIGHT",
        weightKg,
        wfhPts,
        heightCm
      );
    }

    let headCircumferenceForAge: ZScoreResult | null = null;
    if (
      headCm != null &&
      headCm > 0 &&
      supportsHeadCircumference(reference.source, ageMonths)
    ) {
      const hcPts = await load("HEAD_CIRCUMFERENCE_FOR_AGE");
      headCircumferenceForAge = buildZResult(
        "HEAD_CIRCUMFERENCE_FOR_AGE",
        headCm,
        hcPts,
        ageMonths
      );
    }

    const classification = interpretGrowth({
      source: reference.source,
      ageMonths,
      weightForAge,
      heightForAge,
      bmiForAge,
      weightForHeight,
      headCircumferenceForAge,
    });

    const velocity = input.previousVisit
      ? computeGrowthVelocity(input.previousVisit, {
          ageMonths,
          weightKg,
          heightCm,
        })
      : null;

    return {
      reference,
      bmi,
      weightForAge,
      heightForAge,
      bmiForAge,
      weightForHeight,
      headCircumferenceForAge,
      classification,
      expectedWeightKg: weightForAge?.expected ?? null,
      expectedHeightCm: heightForAge?.expected ?? null,
      velocity,
    };
  }
}

/** Functional helper wrapping GrowthCalculator. */
export async function assessGrowth(
  provider: ReferenceDataProvider,
  input: AssessGrowthInput
): Promise<GrowthAssessment> {
  return new GrowthCalculator(provider).assessGrowth(input);
}

export type { Sex, AssessGrowthInput, GrowthAssessment, ReferenceDataProvider };

import type {
  ClinicalFlag,
  NutritionalClassification,
  ReferenceSource,
  SeverityColor,
  ZScoreResult,
} from "./types";

export interface InterpretationInput {
  source: ReferenceSource;
  ageMonths: number;
  weightForAge?: ZScoreResult | null;
  heightForAge?: ZScoreResult | null;
  bmiForAge?: ZScoreResult | null;
  /** Prefer WHZ for <5y when available; BMIZ otherwise. */
  weightForHeight?: ZScoreResult | null;
  headCircumferenceForAge?: ZScoreResult | null;
}

function severityRank(color: SeverityColor): number {
  switch (color) {
    case "green":
      return 0;
    case "yellow":
      return 1;
    case "orange":
      return 2;
    case "red":
      return 3;
  }
}

function worse(a: SeverityColor, b: SeverityColor): SeverityColor {
  return severityRank(a) >= severityRank(b) ? a : b;
}

function labelText(flag: ClinicalFlag): string {
  switch (flag) {
    case "NORMAL":
      return "Normal";
    case "UNDERWEIGHT":
      return "Underweight";
    case "SEVERE_UNDERWEIGHT":
      return "Severe Underweight";
    case "STUNTING":
      return "Stunting";
    case "SEVERE_STUNTING":
      return "Severe Stunting";
    case "WASTING":
      return "Wasting";
    case "SEVERE_WASTING":
      return "Severe Wasting";
    case "OVERWEIGHT":
      return "Overweight";
    case "OBESITY":
      return "Obesity";
    case "SEVERE_OBESITY":
      return "Severe Obesity";
    case "SHORT_STATURE":
      return "Short Stature";
    case "TALL_STATURE":
      return "Tall Stature";
    case "MICROCEPHALY":
      return "Microcephaly";
    case "MACROCEPHALY":
      return "Macrocephaly";
  }
}

const PRIMARY_ORDER: ClinicalFlag[] = [
  "SEVERE_WASTING",
  "SEVERE_UNDERWEIGHT",
  "SEVERE_STUNTING",
  "SEVERE_OBESITY",
  "WASTING",
  "UNDERWEIGHT",
  "STUNTING",
  "OBESITY",
  "SHORT_STATURE",
  "MICROCEPHALY",
  "OVERWEIGHT",
  "TALL_STATURE",
  "MACROCEPHALY",
  "NORMAL",
];

/**
 * WHO / IAP clinical interpretation with severity color coding.
 *
 * - Underweight / Severe Underweight: WAZ < −2 / < −3
 * - Stunting / Severe Stunting: HAZ < −2 / < −3 (WHO / <5y)
 * - Wasting / Severe Wasting: WHZ (preferred) or BMIZ < −2 / < −3 for <5y
 * - Overweight / Obesity / Severe Obesity: WHZ/BMIZ above +2 / +3 (WHO);
 *   IAP school-age uses BMIZ > +1 / +2 / +3 for overweight / obesity / severe
 * - Short stature / Tall stature: IAP / older HAZ < −2 / > +2
 *
 * Extreme |Z| > 3 is noted; classification uses clinical cut-offs on raw Z.
 * Callers may display clamped Z (±3) separately.
 */
export function interpretGrowth(
  input: InterpretationInput
): NutritionalClassification {
  const labels: ClinicalFlag[] = [];
  const notes: string[] = [];
  let severityColor: SeverityColor = "green";

  const waz = input.weightForAge?.z;
  const haz = input.heightForAge?.z;
  const bmiz = input.bmiForAge?.z;
  const whz = input.weightForHeight?.z;
  const hcz = input.headCircumferenceForAge?.z;

  const under5 = input.ageMonths < 60;
  const useWhoRules = input.source === "WHO" || under5;
  const wastingZ = under5 ? (whz ?? bmiz) : bmiz;

  // Weight-for-age
  if (waz != null && Number.isFinite(waz)) {
    if (waz < -3) {
      labels.push("SEVERE_UNDERWEIGHT");
      severityColor = worse(severityColor, "red");
      if (input.weightForAge?.isExtreme) {
        notes.push("WAZ extreme (< −3); display Z may be clamped to ±3.");
      }
    } else if (waz < -2) {
      labels.push("UNDERWEIGHT");
      severityColor = worse(severityColor, "orange");
    }
  }

  // Length / height-for-age
  if (haz != null && Number.isFinite(haz)) {
    if (useWhoRules) {
      if (haz < -3) {
        labels.push("SEVERE_STUNTING");
        severityColor = worse(severityColor, "red");
      } else if (haz < -2) {
        labels.push("STUNTING");
        severityColor = worse(severityColor, "orange");
      }
    } else {
      if (haz < -2) {
        labels.push("SHORT_STATURE");
        severityColor = worse(severityColor, haz < -3 ? "red" : "orange");
        if (haz < -3) notes.push("HAZ < −3: severe short stature.");
      } else if (haz > 2) {
        labels.push("TALL_STATURE");
        severityColor = worse(severityColor, haz > 3 ? "orange" : "yellow");
      }
    }
  }

  // Wasting / adiposity
  if (wastingZ != null && Number.isFinite(wastingZ)) {
    if (wastingZ < -3) {
      labels.push("SEVERE_WASTING");
      severityColor = worse(severityColor, "red");
    } else if (wastingZ < -2) {
      labels.push("WASTING");
      severityColor = worse(severityColor, "orange");
    }

    if (useWhoRules) {
      // WHO: >+2 overweight, >+3 obesity
      if (wastingZ > 3) {
        labels.push("OBESITY");
        severityColor = worse(severityColor, "orange");
      } else if (wastingZ > 2) {
        labels.push("OVERWEIGHT");
        severityColor = worse(severityColor, "yellow");
      }
    } else {
      // IAP older children: BMIZ >+1 overweight, >+2 obesity, >+3 severe
      if (wastingZ > 3) {
        labels.push("SEVERE_OBESITY");
        severityColor = worse(severityColor, "red");
      } else if (wastingZ > 2) {
        labels.push("OBESITY");
        severityColor = worse(severityColor, "orange");
      } else if (wastingZ > 1) {
        labels.push("OVERWEIGHT");
        severityColor = worse(severityColor, "yellow");
      }
    }
  }

  // Head circumference
  if (hcz != null && Number.isFinite(hcz)) {
    if (hcz < -2) {
      labels.push("MICROCEPHALY");
      severityColor = worse(severityColor, hcz < -3 ? "red" : "orange");
    } else if (hcz > 2) {
      labels.push("MACROCEPHALY");
      severityColor = worse(severityColor, hcz > 3 ? "orange" : "yellow");
    }
  }

  const unique: ClinicalFlag[] = [];
  for (const l of labels) {
    if (!unique.includes(l)) unique.push(l);
  }

  if (unique.length === 0) {
    unique.push("NORMAL");
    severityColor = "green";
  }

  let primary: ClinicalFlag = "NORMAL";
  for (const candidate of PRIMARY_ORDER) {
    if (unique.includes(candidate)) {
      primary = candidate;
      break;
    }
  }

  return {
    labels: unique,
    primaryStatus: labelText(primary),
    severityColor,
    notes: notes.length ? notes : undefined,
  };
}

/** Sex as used by growth references (aligned with Prisma Sex enum). */
export type Sex = "MALE" | "FEMALE";

/** Anthropometric indicator for LMS lookup. */
export type GrowthIndicator =
  | "WEIGHT_FOR_AGE"
  | "HEIGHT_FOR_AGE"
  | "BMI_FOR_AGE"
  | "WEIGHT_FOR_HEIGHT"
  | "HEAD_CIRCUMFERENCE_FOR_AGE";

/**
 * Reference chart family.
 * CDC is intentionally excluded — this app uses WHO (<5y) and IAP (≥5y) only.
 */
export type ReferenceSource = "WHO" | "IAP";

/** Published dataset versions used by this engine. */
export type ReferenceVersion = "WHO-2006" | "IAP-2015";

/** LMS Box-Cox parameters for a single x-value (age months or height cm). */
export interface LmsParams {
  L: number;
  M: number;
  S: number;
}

/** One LMS data point on a reference curve. */
export interface LmsPoint extends LmsParams {
  /** Age in months, or height in cm when indicator is WEIGHT_FOR_HEIGHT. */
  xValue: number;
  /** Derived / published chart percentiles (measurement units). */
  p3?: number;
  p15?: number;
  p50?: number;
  p85?: number;
  p97?: number;
}

export interface ZScoreResult {
  /** Raw LMS Z-score (unclamped). */
  z: number;
  /** Z clamped to ±3 for classification display notes. */
  zClamped: number;
  /** Percentile 0–100 derived from raw Z via normal CDF. */
  percentile: number;
  /** Whether raw |Z| exceeded 3. */
  isExtreme: boolean;
  indicator: GrowthIndicator;
  /** Measurement used (kg, cm, or kg/m²). */
  value: number;
  /** Expected median (M) at this age/height. */
  expected: number;
  L: number;
  M: number;
  S: number;
}

export type SeverityColor = "green" | "yellow" | "orange" | "red";

export type ClinicalFlag =
  | "NORMAL"
  | "UNDERWEIGHT"
  | "SEVERE_UNDERWEIGHT"
  | "STUNTING"
  | "SEVERE_STUNTING"
  | "WASTING"
  | "SEVERE_WASTING"
  | "OVERWEIGHT"
  | "OBESITY"
  | "SEVERE_OBESITY"
  | "SHORT_STATURE"
  | "TALL_STATURE"
  | "MICROCEPHALY"
  | "MACROCEPHALY";

export interface NutritionalClassification {
  labels: ClinicalFlag[];
  /** Human-readable primary status for UI / storage. */
  primaryStatus: string;
  severityColor: SeverityColor;
  notes?: string[];
}

export interface AgeBreakdown {
  years: number;
  months: number;
  days: number;
  /** Total completed months (years*12 + months), floored calendar style. */
  totalMonths: number;
  /** Exact age in days (non-negative). */
  totalDays: number;
  /** Fractional months for LMS interpolation (days/30.4375). */
  ageMonthsExact: number;
}

export interface ChartSeriesPoint {
  x: number;
  p3: number;
  p15: number;
  p50: number;
  p85: number;
  p97: number;
}

export interface ReferenceSelection {
  source: ReferenceSource;
